// Implementation outline
function maxScorePartition(s, k) {
  const n = s.length;
  const dist = Array.from({length:n}, ()=>Array(n).fill(0));
  for (let l=0;l<n;l++) {
    const seen = new Set();
    for (let r=l;r<n;r++) { seen.add(s[r]); dist[l][r] = seen.size; }
  }
  const dp = Array.from({length:n+1}, ()=>Array(k+1).fill(-Infinity));
  const par = Array.from({length:n+1}, ()=>Array(k+1).fill(-1));
  for (let i=1;i<=n;i++) dp[i][1] = dist[0][i-1];
  for (let t=2;t<=k;t++){
    for (let i=t;i<=n;i++){
      for (let j=t-1;j<i;j++){
        const v = dp[j][t-1] + dist[j][i-1];
        if (v > dp[i][t]) { dp[i][t] = v; par[i][t] = j; }
      }
    }
  }
  // reconstruction omitted
  return {dp, par};
}
```

## Why This Is Asked
This problem tests a foundational dynamic programming pattern—selecting k non-adjacent elements with maximum sum. It assesses understanding of state definition, transition logic, and reconstruction, making it a classic beginner DP problem.

## Key Concepts
- **State definition**: dp[i][j] represents the optimal sum for the first i elements with exactly j selections
- **Transition logic**: Compare skipping the current element vs. taking it (with the appropriate previous state)
- **Backtracking**: Reconstruct chosen indices by comparing states during backtracking
- **Feasibility constraint**: Maximum selections possible in i elements is floor((i+1)/2)

## Code Example
```javascript
function maxSumNonAdjacent(A, m) {
  const n = A.length;
  const NEG = -Infinity;
  const dp = Array.from({ length: n + 1 }, () => Array(m + 1).fill(NEG));

  for (let i = 0; i <= n; i++) dp[i][0] = 0;

  for (let i = 1; i <= n; i++) {
    for (let j = 1; j <= Math.min(m, Math.floor((i + 1) / 2)); j++) {
      const take = A[i - 1] + (i >= 2 ? dp[i - 2][j - 1] : (j - 1 === 0 ? 0 : NEG));
      const skip = dp[i - 1][j];
      dp[i][j] = Math.max(skip, take);
    }
  }

  const result = dp[n][m];
  const indices = [];
  let i = n, j = m;

  while (i > 0 && j > 0) {
    const take = A[i - 1] + (i >= 2 ? dp[i - 2][j - 1] : (j - 1 === 0 ? 0 : NEG));
    if (dp[i][j] === take) {
      indices.push(i - 1);
      j--;
      i -= 2;
    } else {
      i--;
    }
  }

  return { sum: result, indices: indices.reverse() };
}
```

**Time Complexity:** O(n × m)
**Space Complexity:** O(n × m), or O(m) with optimization.

## Why This Question Is Asked
Tests the ability to extend classic path DP problems with an additional resource constraint, evaluating proficiency in managing 3D DP states, path reconstruction via backtracking, and space optimization.

## Key Concepts
- 3D DP state (i, j, t) tracking exact t boosts used at position (i,j)
- Two transition options: boost or skip the current cell
- Path reconstruction by backtracking through the DP table
- Space optimization: reduce to two rows or maintain a compact parent pointer table

## Code Example
```javascript
function maxPathWithBoosts(grid, k, B) {
  const n = grid.length, m = grid[0].length;
  const NEG = -Infinity;
  const dp = Array.from({ length: n }, () =>
    Array.from({ length: m }, () => new Array(k + 1).fill(NEG))
  );
  dp[0][0][0] = grid[0][0];
  if (k > 0) dp[0][0][1] = grid[0][0] + B;

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      for (let t = 0; t <= k; t++) {
        if (i > 0 && dp[i-1][j][t] !== NEG) {
          dp[i][j][t] = Math.max(dp[i][j][t], dp[i-1][j][t] + grid[i][j]);
        }
        if (j > 0 && dp[i][j-1][t] !== NEG) {
          dp[i][j][t] = Math.max(dp[i][j][t], dp[i][j-1][t] + grid[i][j]);
        }
        if (t > 0) {
          if (i > 0 && dp[i-1][j][t-1] !== NEG) {
            dp[i][j][t] = Math.max(dp[i][j][t], dp[i-1][j][t-1] + grid[i][j] + B);
          }
          if (j > 0 && dp[i][j-1][t-1] !== NEG) {
            dp[i][j][t] = Math.max(dp[i][j][t], dp[i][j-1][t-1] + grid[i][j] + B);
          }
        }
      }
    }
  }

  const boosts = [];
  let i = n - 1, j = m - 1, t = k;
  while (i > 0 || j > 0) {
    const fromTop = i > 0 && dp[i][j][t] === dp[i-1][j][t] + grid[i][j];
    const fromLeft = j > 0 && dp[i][j][t] === dp[i][j-1][t] + grid[i][j];
    const boostedFromTop = i > 0 && t > 0 && dp[i][j][t] === dp[i-1][j][t-1] + grid[i][j] + B;
    const boostedFromLeft = j > 0 && t > 0 && dp[i][j][t] === dp[i][j-1][t-1] + grid[i][j] + B;

    if (boostedFromTop || boostedFromLeft) boosts.push([i, j]);
    if (boostedFromTop || (i > 0 && fromTop && !boostedFromTop)) { i--; }
    else if (j > 0) { j--; if (!boostedFromLeft && !fromLeft) t--; }
  }

  return { maxSum: dp[n-1][m-1][k], boosts: boosts.reverse() };
}
```

## Complexity
- **Time:** O(n × m × k)
- **Space:** O(n × m × k) or O(m × k) with row optimization

