function maxOnesAfterKFlips(s, k) {
  const n = s.length;
  const gain = Array.from({length:n}, (_,i)=> s[i]==='0'?1:-1);
  const NEG = -1e9;
  const dp = Array.from({length:n+1},()=>Array(k+1).fill(NEG));
  const best = Array.from({length:n+1},()=>Array(k+1).fill(NEG));
  dp[0][0]=0;
